svg.script:
function setExpression(name){
  var ids=['neutral','smile','wink','tongue','think'];
  ids.forEach(function(id){
    var el=document.getElementById('expr_'+id);
    if(el){ el.setAttribute('class', id===name ? 'expr active' : 'expr'); }
  });
}
function getExpressions(){ return ['neutral','smile','wink','tongue','think']; }
